<template>
  <div class="space-y-5">
    <UCard v-if="event.registrationMode === 'public'">
      <template #header><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-semibold">Registration forms and fee packages</h3><UButton size="sm" icon="i-lucide-plus" @click="startForm()">Add form</UButton></div></template>
      <p class="text-sm text-slate-600 dark:text-slate-300">Create a local, outstation, or dojo-specific form. Each has its own link, fixed inclusions, student fee and accompanying-person fee. Applicants cannot change the included services. Under-fives are free.</p>
      <div v-if="!event.registrationForms?.length" class="mt-4 text-sm text-slate-500">No fee packages yet. Add one for each audience you want to invite.</div>
      <div v-for="item in event.registrationForms || []" :key="item.id" class="mt-4 rounded-xl border border-slate-200 p-4 dark:border-slate-800">
        <div class="flex flex-wrap items-start justify-between gap-3"><div><h4 class="font-semibold">{{ item.name }} <UBadge :color="item.enabled ? 'success' : 'neutral'" variant="soft">{{ item.enabled ? 'Active' : 'Disabled' }}</UBadge></h4><p v-if="item.audience" class="mt-1 text-sm text-slate-500">{{ item.audience }}</p><p class="mt-1 text-sm">Student {{ formatMinor(item.studentFee) }} · Accompanying person 5+ {{ formatMinor(item.companionFee) }} · Under 5 free · {{ formInclusions(item) }}</p><p class="mt-1 text-xs text-slate-500">{{ requests.filter(row => row.registrationForm?.id === item.id).length }} requests ? {{ formStats(item).enrolled }} enrolled ? Revenue {{ formatMinor(formStats(item).revenue) }} ? Collected {{ formatMinor(formStats(item).collected) }} ? Due {{ formatMinor(formStats(item).outstanding) }}</p></div><div class="flex gap-2"><UButton size="xs" variant="outline" @click="startForm(item)">Edit</UButton><UButton size="xs" color="error" variant="ghost" :loading="busy === `delete-form-${item.id}`" @click="deleteForm(item)">Delete</UButton></div></div>
        <div v-if="item.enabled" class="mt-3 flex flex-wrap gap-2"><UButton size="xs" variant="outline" icon="i-lucide-copy" @click="copyFormLink(item)">Copy link</UButton><UButton size="xs" variant="outline" color="success" :href="`https://wa.me/?text=${encodeURIComponent(`Invitation and registration for ${event.name} (${item.name}): ${formLink(item)}`)}`" target="_blank" rel="noopener">Share on WhatsApp</UButton><UButton size="xs" variant="outline" :href="`/api/public/events/${item.token}/branded-invitation`" target="_blank" rel="noopener">Invitation PDF</UButton><p class="w-full break-all font-mono text-xs text-slate-500">{{ formLink(item) }}</p></div>
      </div>
      <form v-if="editingForm" class="mt-5 space-y-4 rounded-xl border border-primary/30 p-4" @submit.prevent="saveForm"><h4 class="font-semibold">{{ editingFormId ? 'Edit fee package' : 'New fee package' }}</h4><div class="grid gap-3 sm:grid-cols-2"><label>Form name<input v-model="editingForm.name" required maxlength="120" placeholder="Outstation / Gujarat"></label><label>Audience / dojo group<input v-model="editingForm.audience" maxlength="160" placeholder="Gujarat dojos"></label><label class="sm:col-span-2">Description for applicants<textarea v-model="editingForm.description" rows="2" maxlength="2000" /></label><label>Student fee ({{ event.currency }})<input v-model.number="editingForm.studentFee" type="number" min="0" step="0.01" required></label><label>Accompanying person fee, age 5+ ({{ event.currency }})<input v-model.number="editingForm.companionFee" type="number" min="0" step="0.01" required></label><label>Tax (%)<input v-model.number="editingForm.taxPercent" type="number" min="0" max="100" step="0.01" required></label></div><fieldset><legend class="font-medium">Included in these fees</legend><div class="mt-2 flex flex-wrap gap-4 text-sm"><label class="flex items-center gap-2"><input v-model="editingForm.includesTraining" type="checkbox">Training</label><label class="flex items-center gap-2"><input v-model="editingForm.includesMeals" type="checkbox">Meals</label><label class="flex items-center gap-2"><input v-model="editingForm.includesAccommodation" type="checkbox">Accommodation</label><label v-if="event.transportProvided" class="flex items-center gap-2"><input v-model="editingForm.includesTransportOut" type="checkbox">Outward transport</label><label v-if="event.transportProvided" class="flex items-center gap-2"><input v-model="editingForm.includesTransportReturn" type="checkbox">Return transport</label></div></fieldset><label class="flex items-center gap-2 text-sm"><input v-model="editingForm.enabled" type="checkbox">Accept new registrations through this link</label><p class="text-xs text-slate-500">Changes affect new submissions only. Existing requests and bookings keep their quoted fees and inclusions.</p><div class="flex gap-2"><UButton type="submit" size="sm" :loading="busy === 'save-form'">Save form</UButton><UButton type="button" size="sm" color="neutral" variant="ghost" @click="cancelForm">Cancel</UButton></div></form>
    </UCard>
    <UCard>
      <template #header><h3 class="font-semibold">Invitation and public registration</h3></template>
      <p class="text-sm text-slate-600 dark:text-slate-300">The general link uses the event-wide prices and optional service choices. For fixed local or outstation fees, share one of the specific form links above. New requests enter a review queue; they do not reserve places until approved.</p>
      <div class="mt-4 flex flex-wrap items-center gap-2">
        <UButton v-if="!event.publicRegistrationEnabled" :disabled="event.status !== 'open'" :loading="busy === 'link'" icon="i-lucide-link" @click="changeLink('enable')">Enable public form</UButton>
        <template v-else><UButton icon="i-lucide-copy" :loading="busy === 'copy'" @click="copyLink">Copy link</UButton><UButton :href="whatsAppUrl" target="_blank" rel="noopener" color="success" variant="outline" icon="i-lucide-message-circle">Share on WhatsApp</UButton><UButton color="neutral" variant="outline" :loading="busy === 'link'" @click="changeLink('disable')">Disable form</UButton><UButton color="neutral" variant="ghost" :loading="busy === 'link'" @click="changeLink('rotate')">Replace link</UButton></template>
      </div>
      <p v-if="event.publicRegistrationEnabled" class="mt-3 break-all rounded-lg bg-slate-50 p-3 font-mono text-xs dark:bg-slate-900">{{ link }}</p>
      <p v-if="event.status !== 'open'" class="mt-3 text-sm text-amber-600">Open the event to accept new requests. You can still review existing requests while it is closed.</p>
      <div class="mt-5 border-t border-slate-200 pt-4 dark:border-slate-800">
        <h4 class="font-medium">Invitation letters (PDF)</h4>
        <p class="mt-1 text-xs text-slate-500">The generated letter uses the organization's current name and logo, and the invitation text in Event settings. You can also attach an existing PDF, up to 5 MB.</p>
        <a :href="`${endpoint}/branded-invitation`" target="_blank" rel="noopener" class="mt-3 inline-block text-sm text-primary underline">Preview generated invitation</a>
        <div v-if="invitation" class="mt-3 flex flex-wrap items-center gap-3 text-sm"><a :href="`${endpoint}/invitation`" target="_blank" rel="noopener" class="text-primary underline">{{ invitation.filename }}</a><UButton size="xs" color="error" variant="ghost" :loading="busy === 'remove-letter'" @click="removeInvitation">Remove letter</UButton></div>
        <div class="mt-3 flex flex-wrap items-center gap-2"><input ref="invitationInput" type="file" accept="application/pdf,.pdf" aria-label="Invitation PDF" class="min-w-0 text-sm" @change="chooseInvitation"><UButton :disabled="!invitationFile" :loading="busy === 'upload-letter'" size="sm" icon="i-lucide-upload" @click="uploadInvitation">Upload invitation</UButton></div>
      </div>
    </UCard>

    <UCard v-if="summary"><template #header><h3 class="font-semibold">Registrations at a glance</h3></template><dl class="grid gap-3 text-sm sm:grid-cols-3 lg:grid-cols-5"><div v-for="metric in summaryMetrics" :key="metric.label"><dt class="text-slate-500">{{ metric.label }}</dt><dd class="mt-1 text-lg font-semibold">{{ metric.value }}</dd></div></dl><p class="mt-3 text-xs text-slate-500">Enrolled counts exclude waiting-list and cancelled bookings. Payment status comes from the event ledger.</p></UCard>

    <UCard><template #header><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-semibold">Registration requests ({{ pendingRequests.length }} pending)</h3><UButton :href="`${endpoint}/export?kind=requests`" external size="sm" variant="outline" icon="i-lucide-download">Export requests</UButton></div></template>
      <div v-if="pendingRequests.length" class="mb-4 flex flex-wrap items-center gap-2"><UButton size="sm" color="neutral" variant="outline" @click="toggleAll">{{ selectedRequests.length === pendingRequests.length ? 'Clear selection' : 'Select all pending' }}</UButton><span class="text-xs text-slate-500">{{ selectedRequests.length }} selected</span><UButton size="sm" :disabled="!selectedRequests.length" :loading="busy === 'bulk'" @click="bulkReview('approve')">Approve selected</UButton><UButton size="sm" color="error" variant="outline" :disabled="!selectedRequests.length" :loading="busy === 'bulk'" @click="bulkReview('reject')">Reject selected</UButton></div>
      <UAlert v-if="bulkResult" class="mb-4" :color="bulkResult.failed ? 'warning' : 'success'" :title="`${bulkResult.approvedOrRejected} reviewed, ${bulkResult.failed} failed`" :description="bulkResult.results.filter((row: any) => !row.ok).map((row: any) => `${row.reference}: ${row.error}`).join(' · ') || 'All selected requests were reviewed.'" />
      <div v-if="!requests.length" class="py-6 text-center text-sm text-slate-500">No public submissions yet.</div>
      <div v-for="request in requests" :key="request.id" class="border-b border-slate-100 py-5 first:pt-0 last:border-0 last:pb-0 dark:border-slate-800">
        <div class="flex flex-wrap items-start justify-between gap-3"><div class="flex items-start gap-3"><input v-if="request.status === 'submitted'" v-model="selectedRequests" type="checkbox" :value="request.id" class="mt-1" :aria-label="`Select ${request.studentName}`"><div><h4 class="font-semibold">{{ request.studentName }}<span v-if="request.attendees.filter((person: any) => person.type === 'student').length > 1"> + {{ request.attendees.filter((person: any) => person.type === 'student').length - 1 }} students</span> <span class="font-mono text-xs font-normal text-slate-500">{{ request.reference }}</span></h4><p class="mt-1 text-sm text-slate-500">{{ request.registrationForm?.name || (event.registrationMode === 'public' ? 'General event form' : request.sourceType === 'external' ? 'Outside guest' : 'Our dojo') }} · {{ new Date(request.createdAt).toLocaleString() }} · {{ request.attendees.filter((person: any) => person.type === 'student').length }} students · {{ request.attendees.filter((person: any) => person.type === 'parent').length }} accompanying</p></div></div><UBadge :color="request.status === 'approved' ? 'success' : request.status === 'rejected' ? 'error' : 'warning'">{{ request.status }}</UBadge></div>
        <div class="mt-3 grid gap-2 text-sm sm:grid-cols-2"><p>Contact: {{ request.contactName }} · {{ request.contactPhone }}</p><p>DOB: {{ request.dateOfBirth || 'Not supplied' }} · Member no: {{ request.membershipNumber || 'Not supplied' }}</p><p v-if="request.currentGrade">Grade / belt: {{ request.currentGrade }}</p><p>Source: {{ request.sourceDojoName || dojoName(request.dojoId) }}{{ request.sourceCity ? `, ${request.sourceCity}` : '' }}{{ request.sourceState ? `, ${request.sourceState}` : '' }}{{ request.sourceCountry ? `, ${request.sourceCountry}` : '' }}</p><p v-if="request.instructorName">Instructor: {{ request.instructorName }}</p><p>Quoted total: {{ formatMinor(quote(request)) }} · {{ request.waitlist ? 'Waiting list requested' : 'Place requested' }}</p></div>
        <details class="mt-3 text-sm"><summary class="cursor-pointer text-primary">Students, accompanying people and consent</summary><div class="mt-2 space-y-2 rounded-lg bg-slate-50 p-3 dark:bg-slate-900"><p v-for="person in request.attendees" :key="person.id">{{ person.type === 'student' ? 'Student' : 'Accompanying person' }}: {{ person.name || 'Name pending' }} {{ person.relationship ? `(${person.relationship})` : '' }}<span v-if="person.type === 'student'"> · DOB: {{ person.dateOfBirth || request.dateOfBirth }} · Grade: {{ person.currentGrade || request.currentGrade || 'Not supplied' }} · Member no: {{ person.membershipNumber || 'Not supplied' }}<a v-if="person.photoPath" :href="person.photoPath" target="_blank" rel="noopener" class="ml-2 text-primary underline">Photo</a></span> · {{ person.accommodation ? 'bed' : 'no bed' }} · {{ person.transportOut ? 'outward bus' : '' }} {{ person.transportReturn ? 'return bus' : '' }}<span v-if="person.medicalNotes"> · Needs: {{ person.medicalNotes }}</span></p><p>Consent: {{ request.consent.name }} · {{ request.consent.phone }} · {{ request.consent.acceptedAt ? new Date(request.consent.acceptedAt).toLocaleString() : 'pending' }}</p><p v-if="request.notes">Notes: {{ request.notes }}</p></div></details>
        <div v-if="request.customAnswers?.length" class="mt-3 rounded-lg bg-slate-50 p-3 text-sm dark:bg-slate-900"><h5 class="mb-2 font-medium">Additional answers</h5><p v-for="answer in request.customAnswers" :key="answer.id"><strong>{{ answer.label }}:</strong> {{ typeof answer.value === 'boolean' ? answer.value ? 'Yes' : 'No' : answer.value || 'Not answered' }}</p></div>
        <div class="mt-3 flex flex-wrap items-center gap-3 text-sm"><a v-if="request.photoPath" :href="request.photoPath" target="_blank" rel="noopener" class="text-primary underline">View student photo</a><a v-if="request.printToken" :href="`/api/public/event-registration-print/${request.printToken}`" target="_blank" rel="noopener" class="text-primary underline">Download signed-form PDF</a><span v-if="request.physicalCopyReceivedAt" class="text-emerald-700">Signed copy received {{ new Date(request.physicalCopyReceivedAt).toLocaleDateString() }}</span><UButton v-else-if="request.status === 'submitted'" size="xs" variant="outline" :loading="busy === `physical-${request.id}`" @click="markPhysical(request)">Mark signed copy received</UButton></div>
        <p v-if="request.physicalCopyRequired && !request.physicalCopyReceivedAt && request.status === 'submitted'" class="mt-2 text-xs text-amber-700">A signed copy is required before approval.</p>
        <div v-if="request.status === 'submitted'" class="mt-3"><UButton size="xs" color="neutral" variant="ghost" @click="startCorrection(request)">{{ editingRequestId === request.id ? 'Close corrections' : 'Correct submitted details' }}</UButton><form v-if="editingRequestId === request.id" class="mt-2 grid gap-3 rounded-lg border border-slate-200 p-3 text-sm sm:grid-cols-2 dark:border-slate-700" @submit.prevent="saveCorrection(request)"><label>Student name<input v-model="correction.studentName" required maxlength="250" class="mt-1 w-full rounded border p-2"></label><label>Date of birth<input v-model="correction.dateOfBirth" type="date" required class="mt-1 w-full rounded border p-2"></label><label>Membership number<input v-model="correction.membershipNumber" maxlength="100" class="mt-1 w-full rounded border p-2"></label><label v-if="request.registrationForm">Current grade / belt<input v-model="correction.currentGrade" required maxlength="100" class="mt-1 w-full rounded border p-2"></label><label>Contact name<input v-model="correction.contactName" required maxlength="250" class="mt-1 w-full rounded border p-2"></label><label>Contact phone<input v-model="correction.contactPhone" required minlength="5" maxlength="60" class="mt-1 w-full rounded border p-2"></label><label>Emergency name<input v-model="correction.emergencyName" maxlength="250" class="mt-1 w-full rounded border p-2"></label><label>Emergency phone<input v-model="correction.emergencyPhone" maxlength="60" class="mt-1 w-full rounded border p-2"></label><template v-if="request.sourceType === 'external'"><label>Dojo or school<input v-model="correction.sourceDojoName" :required="event.registrationMode === 'linked'" maxlength="250" class="mt-1 w-full rounded border p-2"></label><label v-if="event.registrationMode === 'public'">City<input v-model="correction.sourceCity" required maxlength="150" class="mt-1 w-full rounded border p-2"></label><label>State<input v-model="correction.sourceState" required maxlength="150" class="mt-1 w-full rounded border p-2"></label><label v-if="event.registrationMode === 'public'">Instructor name<input v-model="correction.instructorName" required maxlength="250" class="mt-1 w-full rounded border p-2"></label><label>Country<input v-model="correction.sourceCountry" :required="event.registrationMode === 'linked'" maxlength="150" class="mt-1 w-full rounded border p-2"></label></template><label class="sm:col-span-2">Notes<textarea v-model="correction.notes" maxlength="3000" rows="2" class="mt-1 w-full rounded border p-2" /></label><div class="sm:col-span-2"><UButton type="submit" size="sm" :loading="busy === 'correction'">Save corrections</UButton><p class="mt-2 text-xs text-slate-500">Changes are audited. The applicant's submitted consent and custom answers remain unchanged.</p></div></form></div>
        <div v-if="request.status === 'submitted'" class="mt-4 rounded-xl border border-slate-200 p-3 dark:border-slate-800"><label v-if="event.registrationMode === 'linked'" class="block text-sm font-medium">Approve as<select v-model="reviewMode[request.id]" class="mt-2 w-full rounded-md border border-slate-300 bg-transparent p-2 text-sm dark:border-slate-700"><option value="existing">Link existing OpenDojo student</option><option value="guest">Enroll as event guest</option></select></label>
          <template v-if="event.registrationMode === 'linked' && reviewMode[request.id] === 'existing'"><input v-model="search[request.id]" class="mt-3 w-full rounded-md border border-slate-300 bg-transparent p-2 text-sm dark:border-slate-700" placeholder="Filter by name, phone or member number" :aria-label="`Search students for ${request.studentName}`"><select v-model.number="selected[request.id]" class="mt-2 w-full rounded-md border border-slate-300 bg-transparent p-2 text-sm dark:border-slate-700" :aria-label="`Match student for ${request.studentName}`"><option :value="0">Choose the matching student</option><option v-for="student in candidates(request)" :key="student.id" :value="student.id">{{ student.name }} · {{ student.membershipNumber || student.phone || `#${student.id}` }}</option></select><p v-if="chosenStudent(request)" class="mt-2 text-xs text-slate-500">Selected record: DOB {{ chosenStudent(request).dateOfBirth || 'not stored' }} · member no {{ chosenStudent(request).membershipNumber || 'not stored' }} · phone {{ chosenStudent(request).phone || 'not stored' }}</p></template>
          <p v-else class="mt-2 text-xs text-slate-500">The student will be enrolled in this event only. No regular student profile or tuition account is created.</p>
          <label class="mt-3 flex items-center gap-2 text-sm"><input v-model="waitlist[request.id]" type="checkbox">Place on waiting list instead of reserving a place</label>
          <div class="mt-3 flex flex-wrap gap-2"><UButton size="sm" :disabled="event.registrationMode === 'linked' && reviewMode[request.id] === 'existing' && !selected[request.id]" :loading="busy === request.id" @click="review(request, 'approve')">Approve and create booking</UButton><UButton size="sm" color="error" variant="outline" :loading="busy === request.id" @click="review(request, 'reject')">Reject request</UButton></div>
        </div>
        <p v-else-if="request.bookingId" class="mt-3 text-xs text-slate-500">Created booking #{{ request.bookingId }}</p>
      </div>
    </UCard>
  </div>
</template>
<script setup lang="ts">
import { eventCharge } from '#shared/utils/event-finance'
const props = defineProps<{ event: any, requests: any[], bookings: any[], students: any[], invitation: any, summary: any, endpoint: string }>()
const emit = defineEmits(['changed'])
const toast = useToast()
type FeeForm = { name: string, audience: string, description: string, studentFee: number, companionFee: number, taxPercent: number, includesTraining: boolean, includesMeals: boolean, includesAccommodation: boolean, includesTransportOut: boolean, includesTransportReturn: boolean, enabled: boolean }
const editingForm = ref<FeeForm | null>(null)
const editingFormId = ref<string | null>(null)
function cancelForm() { editingForm.value = null }
function startForm(item?: any) {
  editingFormId.value = item?.id || null
  editingForm.value = item ? { name: item.name, audience: item.audience, description: item.description, studentFee: item.studentFee / 100, companionFee: item.companionFee / 100, taxPercent: item.taxBps / 100, includesTraining: item.includesTraining, includesMeals: item.includesMeals, includesAccommodation: item.includesAccommodation, includesTransportOut: item.includesTransportOut, includesTransportReturn: item.includesTransportReturn, enabled: item.enabled } : { name: '', audience: '', description: '', studentFee: 0, companionFee: 0, taxPercent: props.event.prices.taxBps / 100, includesTraining: true, includesMeals: true, includesAccommodation: false, includesTransportOut: false, includesTransportReturn: false, enabled: true }
}
function formInclusions(item: any) { return [item.includesTraining && 'training', item.includesMeals && 'meals', item.includesAccommodation && 'accommodation', item.includesTransportOut && 'outward transport', item.includesTransportReturn && 'return transport'].filter(Boolean).join(', ') || 'participation only' }
function formStats(item: any) { const rows = props.bookings.filter(row => row.registrationForm?.id === item.id && !['cancelled', 'waitlisted'].includes(row.status)); return { enrolled: rows.length, revenue: rows.reduce((sum, row) => sum + row.balance.net, 0), collected: rows.reduce((sum, row) => sum + row.balance.paid, 0), outstanding: rows.reduce((sum, row) => sum + row.balance.outstanding, 0) } }
function formLink(item: any) { return `${requestUrl.origin}/event-registration/${item.token}` }
async function copyFormLink(item: any) { try { await navigator.clipboard.writeText(formLink(item)); toast.add({ title: 'Form link copied', color: 'success' }) } catch { toast.add({ title: 'Copy the displayed link', color: 'warning' }) } }
async function saveForm() {
  if (!editingForm.value) return
  busy.value = 'save-form'
  try {
    const { taxPercent, studentFee, companionFee, ...rest } = editingForm.value
    await $fetch(`${props.endpoint}/registration-forms`, { method: 'POST', body: { action: editingFormId.value ? 'update' : 'create', id: editingFormId.value || undefined, form: { ...rest, studentFee: Math.round(studentFee * 100), companionFee: Math.round(companionFee * 100), taxBps: Math.round(taxPercent * 100), includesTransportOut: props.event.transportProvided && rest.includesTransportOut, includesTransportReturn: props.event.transportProvided && rest.includesTransportReturn } } })
    editingForm.value = null; emit('changed'); toast.add({ title: 'Registration form saved', color: 'success' })
  } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null }
}
async function deleteForm(item: any) {
  if (!window.confirm(`Delete the ${item.name} registration link? Existing requests and bookings keep their agreed fees.`)) return
  busy.value = `delete-form-${item.id}`
  try { await $fetch(`${props.endpoint}/registration-forms`, { method: 'POST', body: { action: 'delete', id: item.id } }); emit('changed'); toast.add({ title: 'Registration form deleted', color: 'success' }) }
  catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null }
}
const { data: dojos } = await useFetch<any[]>('/api/dojos', { immediate: props.event.registrationMode === 'linked' })
const requestUrl = useRequestURL()
const link = computed(() => `${requestUrl.origin}/event-registration/${props.event.publicRegistrationToken}`)
const whatsAppUrl = computed(() => `https://wa.me/?text=${encodeURIComponent(`Invitation and registration for ${props.event.name}: ${link.value}`)}`)
const { formatMinor } = useMoney(() => props.event.currency)
const busy = ref<string | number | null>(null)
const invitationInput = ref<HTMLInputElement | null>(null)
const invitationFile = ref<File | null>(null)
const selectedRequests = ref<number[]>([])
const bulkResult = ref<any>(null)
const editingRequestId = ref<number | null>(null)
const correction = reactive<any>({})
const reviewMode = reactive<Record<number, 'existing' | 'guest'>>({})
const search = reactive<Record<number, string>>({})
const selected = reactive<Record<number, number>>({})
const waitlist = reactive<Record<number, boolean>>({})
const pendingRequests = computed(() => props.requests.filter(row => row.status === 'submitted'))
const summaryMetrics = computed(() => props.summary ? [
  { label: 'Pending requests', value: props.summary.submitted }, { label: 'Enrolled students', value: props.summary.enrolledStudents },
  ...(props.event.registrationMode === 'linked' ? [{ label: 'Our students', value: props.summary.internalStudents }, { label: 'Outside guests', value: props.summary.guestStudents }] : []),
  { label: 'Accompanying people', value: props.summary.parents }, { label: 'Waiting list', value: props.summary.waitlistedStudents },
  { label: 'Paid bookings', value: props.summary.paidBookings }, { label: 'Part-paid bookings', value: props.summary.partPaidBookings }, { label: 'Fees pending', value: props.summary.pendingFeeBookings },
] : [])
watch(() => props.requests, rows => { for (const row of rows) if (!reviewMode[row.id]) reviewMode[row.id] = props.event.registrationMode === 'public' || row.sourceType === 'external' ? 'guest' : 'existing' }, { immediate: true })
function quote(request: any) { return eventCharge(request.attendees, request.prices).total }
function startCorrection(request: any) { if (editingRequestId.value === request.id) { editingRequestId.value = null; return }; editingRequestId.value = request.id; for (const key of ['studentName', 'dateOfBirth', 'membershipNumber', 'currentGrade', 'contactName', 'contactPhone', 'emergencyName', 'emergencyPhone', 'sourceDojoName', 'sourceCity', 'sourceState', 'sourceCountry', 'instructorName', 'notes']) correction[key] = request[key] || '' }
async function saveCorrection(request: any) { busy.value = 'correction'; try { const keys = request.sourceType === 'external' ? Object.keys(correction) : Object.keys(correction).filter(key => !['sourceDojoName', 'sourceCity', 'sourceState', 'sourceCountry', 'instructorName'].includes(key)); const changes = Object.fromEntries(keys.filter(key => correction[key] !== (request[key] || '')).map(key => [key, correction[key]])); await $fetch(`${props.endpoint}/registration-requests/${request.id}/details`, { method: 'PATCH', body: changes }); editingRequestId.value = null; emit('changed'); toast.add({ title: 'Request corrected', color: 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
async function markPhysical(request: any) { busy.value = `physical-${request.id}`; try { await $fetch(`${props.endpoint}/registration-requests/${request.id}/physical-copy`, { method: 'POST' }); emit('changed'); toast.add({ title: 'Signed copy received', color: 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
function dojoName(id: number | null) { return dojos.value?.find(dojo => dojo.id === id)?.name || (id ? `#${id}` : 'Independent') }
function candidates(request: any) { const term = (search[request.id] || request.studentName || '').trim().toLowerCase(); return props.students.filter(student => (!request.dojoId || student.dojoId === request.dojoId) && `${student.name} ${student.phone} ${student.membershipNumber}`.toLowerCase().includes(term)).slice(0, 50) }
function chosenStudent(request: any) { return props.students.find(student => student.id === selected[request.id]) }
function chooseInvitation(event: Event) { invitationFile.value = (event.target as HTMLInputElement).files?.[0] || null }
async function uploadInvitation() { if (!invitationFile.value) return; busy.value = 'upload-letter'; try { const body = new FormData(); body.append('invitation', invitationFile.value); await $fetch(`${props.endpoint}/invitation`, { method: 'POST', body }); invitationFile.value = null; if (invitationInput.value) invitationInput.value.value = ''; emit('changed'); toast.add({ title: 'Invitation letter uploaded', color: 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
async function removeInvitation() { busy.value = 'remove-letter'; try { await $fetch(`${props.endpoint}/invitation`, { method: 'DELETE' }); emit('changed'); toast.add({ title: 'Invitation removed', color: 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
async function copyLink() { busy.value = 'copy'; try { await navigator.clipboard.writeText(link.value); toast.add({ title: 'Registration link copied', color: 'success' }) } catch { toast.add({ title: 'Copy the displayed link', color: 'warning' }) } finally { busy.value = null } }
async function changeLink(action: 'enable' | 'disable' | 'rotate') { busy.value = 'link'; try { await $fetch(`${props.endpoint}/public-registration`, { method: 'PATCH', body: { action } }); emit('changed'); toast.add({ title: action === 'enable' ? 'Public form enabled' : action === 'disable' ? 'Public form disabled' : 'New link generated', color: 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
function reviewBody(request: any, action: 'approve' | 'reject') { return { action, mode: props.event.registrationMode === 'public' ? 'guest' : reviewMode[request.id] || 'guest', studentId: props.event.registrationMode === 'public' ? undefined : selected[request.id] || undefined, waitlist: Boolean(waitlist[request.id]) } }
async function review(request: any, action: 'approve' | 'reject') { busy.value = request.id; try { await $fetch(`${props.endpoint}/registration-requests/${request.id}`, { method: 'PATCH', body: reviewBody(request, action) }); emit('changed'); toast.add({ title: action === 'approve' ? 'Booking created' : 'Request rejected', color: 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
function toggleAll() { selectedRequests.value = selectedRequests.value.length === pendingRequests.value.length ? [] : pendingRequests.value.map(row => row.id) }
async function bulkReview(action: 'approve' | 'reject') { busy.value = 'bulk'; bulkResult.value = null; try { const chosen = props.requests.filter(row => selectedRequests.value.includes(row.id) && row.status === 'submitted').sort((a, b) => a.id - b.id); const result = await $fetch<any>(`${props.endpoint}/registration-requests/bulk`, { method: 'POST', body: { action, requests: chosen.map(row => ({ id: row.id, mode: reviewMode[row.id] || 'guest', studentId: selected[row.id] || undefined, waitlist: Boolean(waitlist[row.id]) })) } }); bulkResult.value = result; selectedRequests.value = result.results.filter((row: any) => !row.ok).map((row: any) => row.id); emit('changed'); toast.add({ title: `${result.approvedOrRejected} requests reviewed${result.failed ? `, ${result.failed} need attention` : ''}`, color: result.failed ? 'warning' : 'success' }) } catch (error: any) { toast.add({ title: error.data?.statusMessage || error.message, color: 'error' }) } finally { busy.value = null } }
</script>
<style scoped>
form.space-y-4 label { font-size: .875rem; font-weight: 500; }
form.space-y-4 input:not([type=checkbox]), form.space-y-4 textarea { display:block; width:100%; margin-top:.4rem; padding:.6rem .75rem; border:1px solid var(--ui-border); border-radius:.5rem; background:var(--ui-bg); color:var(--ui-text); font-weight:400; }
</style>
